package com.dreamfacilities.servlet;
import com.dreamfacilities.dao.AdminDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/login") public class AdminLoginServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/admin-login.jsp").forward(q,r);}protected void doPost(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{String username=q.getParameter("username"),password=q.getParameter("password");try{if(new AdminDAO().authenticate(username==null?"":username,password==null?"":password)){q.getSession(true).setAttribute("adminUser",username);r.sendRedirect(q.getContextPath()+"/admin");return;}q.setAttribute("error","Incorrect username or password.");}catch(Exception e){q.setAttribute("error","Login failed. Check database setup first.");}q.getRequestDispatcher("/WEB-INF/views/admin-login.jsp").forward(q,r);} }
